{[\hspace{1sp}\cite{BCG}, Conjecture]}\label{conjecturecubic}
Let $\mathbb{K}$ be a complex cubic field and $\mathfrak{f} \neq \mathcal{O}_{\mathbb{K}}$ be an integral ideal in $\mathcal{O}_{\mathbb{K}}$. Fix a complex embedding $\sigma$ of $\mathbb{K}^{+}(\mathfrak{f})$ which extends the fixed complex embedding $\sigma_{\mathbb{C}}$ of $\mathbb{K}$. Fix a class $\mathfrak{c}$ in $\mathrm{Cl}^{+}(\mathfrak{f})$ and an integral ideal $\mathfrak{b}$ in the class $\mathfrak{c}$. Fix a smoothing ideal $\mathfrak{a}$ of norm $N$ such that $N$ is coprime to $6\cdot q\cdot\mathfrak{b}$ where $q\mathbb{Z} = \mathfrak{f} \cap \mathbb{Z}$. Then, the complex number $ \Gamma_{\mathfrak{f}, \mathfrak{b}, \mathfrak{a}}(\varepsilon, h)$ is independent of the choice of admissible base point $h$ as well as from the choice of ideal $\mathfrak{b}$ and it is the image in $\mathbb{C}$ of an algebraic unit $u_{\mathfrak{f}, \mathfrak{c}, \mathfrak{a}}$ in $\mathbb{K}^{+}(\mathfrak{f})$ under the complex embedding $\sigma$ of $\mathbb{K}^{+}(\mathfrak{f})$. Moreover:
\begin{itemize}
\item[(i)] Every embedding of $\mathbb{K}^{+}(\mathfrak{f})$ extending the real embedding of $\mathbb{K}$ maps $u_{\mathfrak{f}, \mathfrak{c}, \mathfrak{a}}$ to the unit circle.
\item[(ii)] If $\mathfrak{c} \to \sigma_{\mathfrak{c}}$ is the Artin map, the explicit reciprocity law is given by $\sigma_{\mathfrak{c}'}(u_{\mathfrak{f}, \mathfrak{c}, \mathfrak{a}}) = u_{\mathfrak{f}, \mathfrak{c}\mathfrak{c}', \mathfrak{a}}$ for any class $\mathfrak{c}'$ in the narrow ray class group at $\mathfrak{f}$. 
\end{itemize}

{[\hspace{1sp}\cite{BCG}, Theorem 3.2]}\label{KLFcubic}
The modulus of the complex number $ \Gamma_{\mathfrak{f}, \mathfrak{b}, \mathfrak{a}}(\varepsilon, h) $ is independent of the choice of admissible base point $h$ and it satisfies the Kronecker limit formula:
$$N\cdot \zeta'_{\mathfrak{f}}(\mathfrak{b}, 0) - \zeta'_{\mathfrak{f}}(\mathfrak{a}\mathfrak{b}, 0)  = \log\left|\Gamma_{\mathfrak{f}, \mathfrak{b}, \mathfrak{a}}(\varepsilon, h)\right|^2.$$

{[Vague form 2]}\label{conjecturevagueformdeux}
Let $\mathbb{K}$ be an ATR field of degree $n = r+2 \geq 3$. Suppose that $\mathfrak{f}, \mathfrak{b}, \mathfrak{a}$ are as above and set $N = \mathcal{N}(\mathfrak{a})$. Let $\varepsilon_1, \dots, \varepsilon_r$ be a set of non-degenerate fundamental units for $U_{\mathfrak{f}}^+$. Then, for each permutation $\rho \in \mathfrak{S}_r$, there isa n admissible base point $h_\rho$ and there are orientation signs $\mu_{\rho}, \nu_{\rho} \in \{\pm 1\}$ such that the complex number
\begin{equation}\label{uvagueformdeux}u = I_{r,\mathfrak{f}, \mathfrak{b}, \mathfrak{a}}(\varepsilon_1, \dots, \varepsilon_r ; \underline{h}, \underline{\mu}, \underline{\nu})^{\mathcal{D}(N, n)}
\end{equation}
satisfies:
\begin{enumerate}
\item An algebraicity statement: the complex number $u$ is an algebraic unit in $\mathbb{K}^{+}(\mathfrak{f})$.
\item A Kronecker limit formula of the form:
\begin{equation}\label{klfvagueformdeux}
N\zeta'_{\mathfrak{f}}(\mathfrak{b}, 0) - \zeta'_{\mathfrak{f}}(\mathfrak{a}\mathfrak{b}, 0) = \frac{1}{\mathcal{D}(N, n)}\log\left|u\right|^2.
\end{equation}
\end{enumerate}

\label{lemmadepidealhrho}
Let $h, h' \in \mathfrak{f}\mathfrak{b}^{-1}$ be two admissible base points. Let $m$ and $m'$ be the maximal integers satisfying $h/m, h'/m' \in \mathfrak{f}\mathfrak{b}^{-1}$. Suppose that the ideals $(h/m)\mathcal{O}_{\mathbb{K}}$ and $(h'/m')\mathcal{O}_{\mathbb{K}}$ are equal. Consider the primitive linear forms $a$ and $a'$ given as before by:
\begin{align*}
\lambda m^{r+1} a(y)&  = \mathrm{det}_{B_L}(h, u_1 h, \dots, u_rh, y)\\
\lambda' (m')^{r+1} a'(y) &= \mathrm{det}_{B_L}(h', u_1 h', \dots, u_rh', y) 
\end{align*}
where $\lambda, \lambda'$ are positive integers and $u_1, \dots, u_r$ are any totally positive units for which these linear forms are non-zero. Then $\mathfrak{D}(a, L) = \mathfrak{D}(a', L)$.

{[Rank one abelian Stark conjecture for ATR fields]}
Let $\mathbb{K}$ be an ATR field and $\mathfrak{f} \neq \mathcal{O}_{\mathbb{K}}$ be an integral ideal. Write $e_{\mathfrak{f}}$ for the number of roots of unity in $\mathbb{K}^{+}(\mathfrak{f})$. Fix a complex embedding $\sigma$ of $\mathbb{K}^{+}(\mathfrak{f})$ extending a fixed complex embedding $\sigma_{\mathbb{C}}$ of $\mathbb{K}$. There is a unit $u_{Stark}$ in $\mathbb{K}^{+}(\mathfrak{f})$ such that 
\begin{itemize}
\item For any class $\mathfrak{c}$ in $\mathrm{Cl}^{+}(\mathfrak{f})$, if $\sigma_{\mathfrak{c}} \in \mathrm{Gal}(\mathbb{K}^{+}(\mathfrak{f})/\mathbb{K})$ is the image of $\mathfrak{c}$ under Artin's map then:
$$\zeta'_{\mathfrak{f}}(\mathfrak{c}, 0) = -\frac{1}{e_{\mathfrak{f}}} \log|\sigma\left(u_{Stark}^{\sigma_{\mathfrak{c}}}\right)|^2.$$
\item Every complex embedding of $\,\mathbb{K}^{+}(\mathfrak{f})$ above a real embedding of $\,\mathbb{K}$ maps $u_{Stark}$ to the unit circle.
\item The number field $\mathbb{K}^{+}(\mathfrak{f})(u_{Stark}^{1/e_{\mathfrak{f}}})$ is an abelian extension of $\,\mathbb{K}$.
\end{itemize}

\label{tmin}
Let $\mathcal{A}$ be the matrix defined in (\ref{defatable}). 
\begin{itemize}
\item[(i)] Let $\mathcal{B}' \in M_{r+1}(\mathbb{Z})$ be a square matrix of size $r+1$ such that $\mathcal{A} \cdot \mathcal{B}' = d I_{r+1}$ for some integer $d$. Then $t$ divides $d$.
\item[(ii)] Any uniform positive dual family $\underline{\alpha}'$ to $\underline{a}$ in $L$ satisfies $\underline{a} \cdot \underline{\alpha}' = d I_{r+1}$ where $t$ divide $d$.
\item[(iii)] If $\underline{\alpha}, \underline{\alpha}'$ are uniform positive dual families to $\underline{a}$ in $L$ satisfying $\underline{a} \cdot \underline{\alpha} = d I_{r+1}$ and $ \underline{a} \cdot \underline{\alpha}' = d' I_{r+1}$ then for all $0 \leq j \leq r$, $d'\alpha_j - d\alpha'_j \in \mathrm{gcd}(d, d')\mathbb{Z}\gamma$.
\end{itemize}

\label{definitionlevel}
The level $\ell = \ell(u_1, \dots, u_r ; h)$ associated to the unit system $u_1, \dots, u_r$ and to the weakly admissible base point $h$ is defined as the maximal integer satisfying
$$\tilde{\alpha}_0h, \dots, \tilde{\alpha}_rh \in m\ell L + \mathbb{Z} h.$$

\label{fundam}
Let $\epsilon = \mathrm{sign}(\mathcal{N}(h)) \in \{-1,+1\}$.
\begin{itemize}
\item[(i)] The family $\epsilon\tilde{\underline{\alpha}} h = (\epsilon\tilde{\alpha}_0 h, \dots, \epsilon\tilde{\alpha}_r h)$ is a uniform positive dual family to $\underline{a}$ in $L$ such that $\underline{a} \cdot (\epsilon\tilde{\underline{\alpha}} h) = m \ell t I_{r+1}$. 
\item[(ii)] The following fundamental relation holds in $\mathbb{Z}$:
\begin{equation}\label{formulafundam}
\lambda \ell t = \frac{|\mathcal{N}(h/m)|}{\mathcal{N}(L)} \tilde{\lambda} \tilde{t}.
\end{equation}
\item[(iii)] For any $0 \leq j \leq r$ there is some integer $m_j \in \mathbb{Z}$ such that
\begin{equation}\label{eqlienalpha}
\alpha_j = \frac{\tilde{\alpha}_j h + m_j h}{\epsilon m \ell}.
\end{equation}
\end{itemize}

\label{lemmalinktarget}
The different ideals $\mathfrak{D}(a, L)$ and $\mathfrak{D}(\tilde{a}, \mathcal{O}_{\mathbb{K}})$ are primitive integral ideals related by: 
$$\lambda \cdot\mathfrak{D}(a, L) = \tilde{\lambda}\cdot \frac{\mathcal{N}(h/m)}{\mathcal{N}(L)}\cdot\frac{m}{h}L\cdot\mathfrak{D}(\tilde{a}, \mathcal{O}_{\mathbb{K}}).$$

\label{calculdifferent}
Let $B = [e_0, \dots, e_{r+1}]$ be a $\mathbb{Z}$-basis of a fractional ideal $I$ and $B' = [e'_0, \dots, e'_{r+1}]$ be any $\mathbb{Q}$-basis of $\mathbb{K}$. Let $f$ be a non-zero $\mathbb{Q}$-linear form on the $\mathbb{Q}$-vector space $\mathbb{K}$. We may define $\mathcal{M} \in M_{r+2}(\mathbb{Q})$ to be the matrix whose coefficients are the rational numbers $f(e_i e'_j)$ for $0 \leq i,j \leq r+1$. Then $\mathfrak{D}(f, I)^{-1}$ is explicitly parametrised in the basis $B'$ as the image of $\mathbb{Z}^{r+2}$ under the $\mathbb{Q}$-linear isomorphism $\iota : \mathbb{Q}^{r+2} \to \mathbb{K}$ defined by:
$$\iota\begin{pmatrix} x_0 \\ x_1 \\ \vdots \\ x_{r+1}  \end{pmatrix} = (e'_0, \dots, e'_{r+1}) \times \mathcal{M}^{-1} \times \begin{pmatrix} x_0 \\ x_1 \\ \vdots \\ x_{r+1}  \end{pmatrix}.$$

\label{theoremchoiceh}
Suppose that $\mathbb{K}$ is an ATR field of degree $n = r+2 \geq 3$. Fix an integral ideal $\mathfrak{f} \neq \mathcal{O}_{\mathbb{K}}$. Set $q\mathbb{Z} = \mathfrak{f} \cap \mathbb{Z}$ with $q >0$ and $Q > 0$ to be the maximal integer satisfying $\mathfrak{f} \subset Q\mathcal{O}_{\mathbb{K}}$. Fix a smoothing ideal $\mathfrak{a}$ of norm $N$ coprime to $q$. Fix an integral ideal $\mathfrak{b}$ coprime to $\mathfrak{f}$. Fix a set of non-degenerate fundamental units $\varepsilon_1, \dots, \varepsilon_r$ for $U_{\mathfrak{f}}^+$. Let $\widetilde{\mathfrak{D}}_{\rho}$ denote the overflow ideal of the unit system $[\varepsilon_{\rho(1)}|\dots|\varepsilon_{\rho(r)}]$ for $\rho \in \mathfrak{S}_{r}$. Let us assume that for all $\rho$ the overflow ideal $\widetilde{\mathfrak{D}}_{\rho}$ is coprime to $\mathfrak{f}$ (see (\ref{hypothesisprimediff})) and to $N$. Let us also suppose that the collection of overflow ideals $\widetilde{\mathfrak{D}}_{\rho}$ satisfy (\ref{hypothesisconstantclass}) (or simply that $\mathcal{O}_{\mathbb{K}}/\mathfrak{f}$ is cyclic). Then there is a helper ideal $\mathfrak{H}$ coprime to $q\cdot N\cdot\prod_{\rho}\tilde{t}_{\rho}$ and there are integers $m_{\rho} > 0$ such that the fractional ideals  
\begin{equation}\label{eqthdefh}\frac{qN}{\mathfrak{a}\mathfrak{b}} \widetilde{\mathfrak{D}}_{\rho}\cdot m_{\rho}\cdot \mathfrak{H}
\end{equation}
are generated by admissible base points $h_{\rho}$ which are compatible in the sense of Definition \ref{defcompatible}. In addition:
$$\begin{cases} \mathfrak{D}(a_{\rho}, L) & = \frac{\mathfrak{f}}{Q}\cdot \frac{p_{\mathfrak{H}}}{\mathfrak{H}} \cdot\mathfrak{a}, \\ 
\lambda_{\rho} & = \tilde{\lambda}_{\rho} \cdot\mathcal{N}(\widetilde{\mathfrak{D}}_{\rho}) \cdot\frac{Q q^{n-1}}{\mathcal{N}(\mathfrak{f})} \cdot N^{n-2} \cdot p_{\mathfrak{H}}^{n-2}, \\
 \ell_{\rho} t_{\rho} & = \frac{q}{Q} \cdot N \cdot p_{\mathfrak{H}} \cdot \tilde{t}_{\rho} \\ \ell_{\rho} & \in N \cdot p_{\mathfrak{H}} \,\mathbb{Z}  \\ \end{cases} $$
where $\mathfrak{H} \cap \mathbb{Z} = p_{\mathfrak{H}} \mathbb{Z}$. If we assume further that the integral ideal $I = \mathfrak{f}/Q$ is such that $\mathcal{O}_{\mathbb{K}}/I$ is cyclic then $\ell_{\rho} \in \frac{q}{Q} \cdot N \cdot p_{\mathfrak{H}} \, \mathbb{Z}$ and $\tilde{t}_{\rho}$ divides $t_{\rho}$. Lastly, in the special case where we assume that $\mathcal{O}_{\mathbb{K}}/\mathfrak{f}$ is cylic, that $\tilde{\lambda}_{\rho} = 1$ and that $\tilde{t}_{\rho}$ is coprime to $q$, we have $\ell_{\rho} = q \cdot N \cdot p_{\mathfrak{H}} \cdot \tilde{t}_{\rho}$ and $t_{\rho} = s_{\rho} = 1$.

\label{propexistencebasepoints}
Under the hypotheses of Theorem \ref{theoremchoiceh} there is a helper ideal $\mathfrak{H}$ coprime to $q\cdot N \cdot \prod_{\rho} \tilde{t}_{\rho}$ and there are integers $m_{\rho} > 0$ such that the fractional ideals  
\begin{equation}\label{eqpropdefh}\frac{qN}{\mathfrak{a}\mathfrak{b}} \widetilde{\mathfrak{D}}_{\rho}\cdot m_{\rho}\cdot \mathfrak{H}
\end{equation}
are generated by admissible base points $h_{\rho}$ which are compatible in the sense of Definition \ref{defcompatible}. In addition:
$$\begin{cases} \mathfrak{D}(a_{\rho}, L) & = \frac{\mathfrak{f}}{Q}\cdot \frac{p_{\mathfrak{H}}}{\mathfrak{H}} \cdot\mathfrak{a}, \\ \lambda_{\rho} & = \tilde{\lambda}_{\rho} \cdot\mathcal{N}(\widetilde{\mathfrak{D}}_{\rho}) \cdot\frac{Q q^{n-1}}{\mathcal{N}(f)} \cdot N^{n-2} \cdot p_{\mathfrak{H}}^{n-2} \\
\ell_{\rho}t_{\rho} &= \frac{q}{Q} \cdot N \cdot p_{\mathfrak{H}} \cdot \tilde{t}_{\rho}\end{cases}$$
where $p_{\mathfrak{H}}\, \mathbb{Z} = \mathfrak{H} \cap \mathbb{Z}$.

\begin{itemize}
\item This proposition is the main tool we use to produce sets of compatible base points $(h_{\rho})_{\rho}$ algorithmically and such sets are the ones we generally use in our computations to put our conjectures to the test. 
\item When one of the hypotheses (\ref{hypothesisprimediff}), (\ref{hypothesisconstantclass}) are not satisfied, minor tweakings to the form (\ref{formcompatible}) should also allow us to find simple sets of compatible base points. Some examples to showcase what sort of computations remain possible are presented in [\hspace{1sp}\cite{thesis}, Section IV.2.6].
\item When choosing a helper ideal, one should try to minimise the value of the positive integer $p_{\mathfrak{H}}$ defined by $\mathfrak{H} \cap \mathbb{Z} = p_{\mathfrak{H}} \,\mathbb{Z}$. Indeed, as we explain in section \ref{computingarithmetic}, the complexity of the computation of the arithmetic $G_r$ function (\ref{arithmeticgrshape}) is linear in $\ell_{\rho}$. In section \ref{sectiondeterminationlt} we show that $p_{\mathfrak{H}} \mid \ell_{\rho}$, thus the complexity of the evaluation of the higher elliptic unit using the helper ideal $\mathfrak{H}$ is linear in $p_{\mathfrak{H}}$.
\end{itemize}
